package ext

import "fmt"

type Document struct {
	Version   string     `yaml:"version,omitempty"`
	Namespace string     `yaml:"namespace,omitempty"`
	Flags     []*Flag    `yaml:"flags,omitempty"`
	Segments  []*Segment `yaml:"segments,omitempty"`
}

type Flag struct {
	Key         string     `yaml:"key,omitempty"`
	Name        string     `yaml:"name,omitempty"`
	Type        string     `yaml:"type,omitempty"`
	Description string     `yaml:"description,omitempty"`
	Enabled     bool       `yaml:"enabled"`
	Variants    []*Variant `yaml:"variants,omitempty"`
	Rules       []*Rule    `yaml:"rules,omitempty"`
	Rollouts    []*Rollout `yaml:"rollouts,omitempty"`
}

type Variant struct {
	Key         string      `yaml:"key,omitempty"`
	Name        string      `yaml:"name,omitempty"`
	Description string      `yaml:"description,omitempty"`
	Attachment  interface{} `yaml:"attachment,omitempty"`
}

type Rule struct {
	Segment       *SegmentEmbed   `yaml:"segment,omitempty"`
	Rank          uint            `yaml:"rank,omitempty"`
	Distributions []*Distribution `yaml:"distributions,omitempty"`
}

// IsSegment is implemented by both supported rule segment representations.
type IsSegment interface {
	isSegment()
}

// SegmentKey is the shorthand form of a rule segment.
type SegmentKey string

func (SegmentKey) isSegment() {}

// Segments is the object form of a rule segment.
type Segments struct {
	Keys            []string `yaml:"keys"`
	SegmentOperator string   `yaml:"operator"`
}

func (Segments) isSegment() {}

// SegmentEmbed allows a rule's segment to be either a key or a group of keys.
type SegmentEmbed struct {
	IsSegment
}

// MarshalYAML preserves the representation held by SegmentEmbed.
func (s *SegmentEmbed) MarshalYAML() (interface{}, error) {
	if s == nil {
		return nil, fmt.Errorf("invalid segment: missing value")
	}

	switch segment := s.IsSegment.(type) {
	case SegmentKey:
		if segment == "" {
			return nil, fmt.Errorf("invalid segment: empty key")
		}
		return string(segment), nil
	case *SegmentKey:
		if segment == nil || *segment == "" {
			return nil, fmt.Errorf("invalid segment: empty key")
		}
		return string(*segment), nil
	case Segments:
		if len(segment.Keys) == 1 {
			segment.SegmentOperator = "OR_SEGMENT_OPERATOR"
		}
		if err := validateSegments(segment); err != nil {
			return nil, err
		}
		return segment, nil
	case *Segments:
		if segment == nil {
			return nil, fmt.Errorf("invalid segment: missing value")
		}
		value := *segment
		if len(value.Keys) == 1 {
			value.SegmentOperator = "OR_SEGMENT_OPERATOR"
		}
		if err := validateSegments(value); err != nil {
			return nil, err
		}
		return value, nil
	default:
		return nil, fmt.Errorf("invalid segment: unsupported value %T", s.IsSegment)
	}
}

// UnmarshalYAML accepts a key or an object with keys and an operator.
func (s *SegmentEmbed) UnmarshalYAML(unmarshal func(interface{}) error) error {
	var raw interface{}
	if err := unmarshal(&raw); err != nil {
		return err
	}

	switch value := raw.(type) {
	case string:
		if value == "" {
			return fmt.Errorf("invalid segment: empty key")
		}
		s.IsSegment = SegmentKey(value)
		return nil
	case map[interface{}]interface{}:
		fields := make(map[string]interface{}, len(value))
		for key, field := range value {
			name, ok := key.(string)
			if !ok {
				return fmt.Errorf("invalid segment: unsupported field %v", key)
			}
			fields[name] = field
		}
		return s.unmarshalSegmentMap(fields)
	case map[string]interface{}:
		return s.unmarshalSegmentMap(value)
	default:
		return fmt.Errorf("invalid segment: expected a key or keys and operator, got %T", raw)
	}
}

func (s *SegmentEmbed) unmarshalSegmentMap(fields map[string]interface{}) error {
	var segment Segments
	var hasKeys, hasOperator bool
	var operatorValue interface{}
	for key, field := range fields {
		switch key {
		case "keys":
			hasKeys = true
			keys, ok := field.([]interface{})
			if !ok {
				return fmt.Errorf("invalid segment: keys must be a list of strings")
			}
			for _, key := range keys {
				name, ok := key.(string)
				if !ok || name == "" {
					return fmt.Errorf("invalid segment: keys must be nonempty strings")
				}
				segment.Keys = append(segment.Keys, name)
			}
		case "operator":
			hasOperator = true
			operatorValue = field
		default:
			return fmt.Errorf("invalid segment: unsupported field %v", key)
		}
	}
	if !hasKeys || len(segment.Keys) == 0 {
		return fmt.Errorf("invalid segment: keys must be a nonempty list")
	}
	if !hasOperator {
		return fmt.Errorf("invalid segment: missing operator")
	}
	if len(segment.Keys) == 1 {
		s.IsSegment = SegmentKey(segment.Keys[0])
		return nil
	}
	operator, ok := operatorValue.(string)
	if !ok {
		return fmt.Errorf("invalid segment: operator must be a string")
	}
	segment.SegmentOperator = operator
	if err := validateSegments(segment); err != nil {
		return err
	}
	s.IsSegment = segment
	return nil
}

func validateSegments(segment Segments) error {
	if len(segment.Keys) == 0 {
		return fmt.Errorf("invalid segment: keys must be a nonempty list")
	}
	for _, key := range segment.Keys {
		if key == "" {
			return fmt.Errorf("invalid segment: keys must be nonempty strings")
		}
	}
	if segment.SegmentOperator != "AND_SEGMENT_OPERATOR" && segment.SegmentOperator != "OR_SEGMENT_OPERATOR" {
		return fmt.Errorf("invalid segment: unsupported operator %q", segment.SegmentOperator)
	}
	return nil
}

type Distribution struct {
	VariantKey string  `yaml:"variant,omitempty"`
	Rollout    float32 `yaml:"rollout,omitempty"`
}

type Rollout struct {
	Description string         `yaml:"description,omitempty"`
	Segment     *SegmentRule   `yaml:"segment,omitempty"`
	Threshold   *ThresholdRule `yaml:"threshold,omitempty"`
}

type SegmentRule struct {
	Key      string   `yaml:"key,omitempty"`
	Keys     []string `yaml:"keys,omitempty"`
	Operator string   `yaml:"operator,omitempty"`
	Value    bool     `yaml:"value,omitempty"`

package ext

import (
	"context"
	"encoding/json"
	"fmt"
	"io"

	"github.com/blang/semver/v4"
	"go.flipt.io/flipt/rpc/flipt"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
	"gopkg.in/yaml.v2"
)

type Creator interface {
	GetNamespace(context.Context, *flipt.GetNamespaceRequest) (*flipt.Namespace, error)
	CreateNamespace(context.Context, *flipt.CreateNamespaceRequest) (*flipt.Namespace, error)
	CreateFlag(context.Context, *flipt.CreateFlagRequest) (*flipt.Flag, error)
	CreateVariant(context.Context, *flipt.CreateVariantRequest) (*flipt.Variant, error)
	CreateSegment(context.Context, *flipt.CreateSegmentRequest) (*flipt.Segment, error)
	CreateConstraint(context.Context, *flipt.CreateConstraintRequest) (*flipt.Constraint, error)
	CreateRule(context.Context, *flipt.CreateRuleRequest) (*flipt.Rule, error)
	CreateDistribution(context.Context, *flipt.CreateDistributionRequest) (*flipt.Distribution, error)
	CreateRollout(context.Context, *flipt.CreateRolloutRequest) (*flipt.Rollout, error)
}

type Importer struct {
	creator   Creator
	namespace string
	createNS  bool
}

type ImportOpt func(*Importer)

func WithNamespace(ns string) ImportOpt {
	return func(i *Importer) {
		i.namespace = ns
	}
}

func WithCreateNamespace() ImportOpt {
	return func(i *Importer) {
		i.createNS = true
	}
}

func NewImporter(store Creator, opts ...ImportOpt) *Importer {
	i := &Importer{
		creator: store,
	}

	for _, opt := range opts {
		opt(i)
	}

	return i
}

func (i *Importer) Import(ctx context.Context, r io.Reader) (err error) {
	var (
		dec = yaml.NewDecoder(r)
		doc = new(Document)
	)

	if err := dec.Decode(doc); err != nil {
		return fmt.Errorf("unmarshalling document: %w", err)
	}

	v := latestVersion
	if doc.Version != "" {
		v, err = semver.ParseTolerant(doc.Version)
		if err != nil {
			return fmt.Errorf("parsing document version: %w", err)
		}

		var found bool
		for _, sv := range supportedVersions {
			if found = sv.EQ(v); found {
				break
			}
		}

		if !found {
			return fmt.Errorf("unsupported version: %s", doc.Version)
		}
	}

	// check if document namespace matches cli namespace if both are set
	if doc.Namespace != "" && i.namespace != "" && doc.Namespace != i.namespace {
		return fmt.Errorf("namespace mismatch: namespaces must match in file and args if both provided: %s != %s", doc.Namespace, i.namespace)
	}

	// prefer document namespace over cli namespace, but use cli namespace if
	// document namespace is empty
	var namespace = doc.Namespace
	if namespace == "" {
		namespace = i.namespace
	}

	if i.createNS && namespace != "" && namespace != flipt.DefaultNamespace {
		_, err := i.creator.GetNamespace(ctx, &flipt.GetNamespaceRequest{
			Key: namespace,
		})

		if status.Code(err) != codes.NotFound {
			return err
		}

		_, err = i.creator.CreateNamespace(ctx, &flipt.CreateNamespaceRequest{
			Key:  namespace,
			Name: namespace,
		})
		if err != nil {
			return err
		}
	}

	var (
		// map flagKey => *flag
		createdFlags = make(map[string]*flipt.Flag)
		// map segmentKey => *segment
		createdSegments = make(map[string]*flipt.Segment)
		// map flagKey:variantKey => *variant
		createdVariants = make(map[string]*flipt.Variant)
	)

	// create flags/variants
	for _, f := range doc.Flags {
		if f == nil {
			continue
		}

		req := &flipt.CreateFlagRequest{
			Key:          f.Key,
			Name:         f.Name,
			Description:  f.Description,
			Enabled:      f.Enabled,
			NamespaceKey: namespace,
		}

		// support explicitly setting flag type from 1.1
		if f.Type != "" {
			if err := ensureFieldSupported("flag.type", semver.Version{
				Major: 1,
				Minor: 1,
			}, v); err != nil {
				return err
			}

			req.Type = flipt.FlagType(flipt.FlagType_value[f.Type])
		}

		flag, err := i.creator.CreateFlag(ctx, req)
		if err != nil {
			return fmt.Errorf("creating flag: %w", err)
		}

		for _, v := range f.Variants {
			if v == nil {
				continue
			}

			var out []byte

			if v.Attachment != nil {
				converted := convert(v.Attachment)
				out, err = json.Marshal(converted)
				if err != nil {
					return fmt.Errorf("marshalling attachment: %w", err)
				}
			}

			variant, err := i.creator.CreateVariant(ctx, &flipt.CreateVariantRequest{
				FlagKey:      f.Key,
				Key:          v.Key,
				Name:         v.Name,
				Description:  v.Description,
				Attachment:   string(out),
				NamespaceKey: namespace,
			})

			if err != nil {
				return fmt.Errorf("creating variant: %w", err)
			}

			createdVariants[fmt.Sprintf("%s:%s", flag.Key, variant.Key)] = variant
		}

		createdFlags[flag.Key] = flag
	}

	// create segments/constraints
	for _, s := range doc.Segments {
		if s == nil {
			continue
		}

		segment, err := i.creator.CreateSegment(ctx, &flipt.CreateSegmentRequest{
			Key:          s.Key,
			Name:         s.Name,
			Description:  s.Description,
			MatchType:    flipt.MatchType(flipt.MatchType_value[s.MatchType]),
			NamespaceKey: namespace,
		})

		if err != nil {
			return fmt.Errorf("creating segment: %w", err)
		}

		for _, c := range s.Constraints {
			if c == nil {
				continue
			}

			_, err := i.creator.CreateConstraint(ctx, &flipt.CreateConstraintRequest{
				SegmentKey:   s.Key,
				Type:         flipt.ComparisonType(flipt.ComparisonType_value[c.Type]),
				Property:     c.Property,
				Operator:     c.Operator,
				Value:        c.Value,
				NamespaceKey: namespace,
			})

			if err != nil {
				return fmt.Errorf("creating constraint: %w", err)
			}
		}

		createdSegments[segment.Key] = segment
	}

	// create rules/distributions
	for _, f := range doc.Flags {
		if f == nil {
			continue
		}

		// loop through rules
		for idx, r := range f.Rules {
			if r == nil {
				continue
			}

			// support implicit rank from version >=1.1
			rank := int32(r.Rank)
			if rank == 0 && v.GE(semver.Version{Major: 1, Minor: 1}) {
				rank = int32(idx) + 1
			}

			fcr := &flipt.CreateRuleRequest{
				FlagKey:      f.Key,
				Rank:         rank,
				NamespaceKey: namespace,
			}

			if r.Segment == nil {
				return fmt.Errorf("rule %s/%s/%d must have a segment", namespace, f.Key, idx)
			}

			switch segment := r.Segment.IsSegment.(type) {
			case SegmentKey:
				if segment == "" {
					return fmt.Errorf("rule %s/%s/%d must have a segment key", namespace, f.Key, idx)
				}
				fcr.SegmentKey = string(segment)
				fcr.SegmentOperator = flipt.SegmentOperator_OR_SEGMENT_OPERATOR
			case Segments:
				if len(segment.Keys) == 0 {
					return fmt.Errorf("rule %s/%s/%d must have segment keys", namespace, f.Key, idx)
				}
				if len(segment.Keys) == 1 {
					fcr.SegmentKey = segment.Keys[0]
					fcr.SegmentOperator = flipt.SegmentOperator_OR_SEGMENT_OPERATOR
					break
				}
				if err := ensureFieldSupported("flag.rules[*].segment.keys", semver.Version{
					Major: 1,
					Minor: 2,
				}, v); err != nil {
					return err
				}
				operator, ok := flipt.SegmentOperator_value[segment.SegmentOperator]
				if !ok {
					return fmt.Errorf("rule %s/%s/%d has invalid segment operator %q", namespace, f.Key, idx, segment.SegmentOperator)
				}
				fcr.SegmentKeys = segment.Keys
				fcr.SegmentOperator = flipt.SegmentOperator(operator)
			default:
				return fmt.Errorf("rule %s/%s/%d has invalid segment", namespace, f.Key, idx)
			}

			rule, err := i.creator.CreateRule(ctx, fcr)

			if err != nil {
				return fmt.Errorf("creating rule: %w", err)
			}

			for _, d := range r.Distributions {
				if d == nil {
					continue
				}

				variant, found := createdVariants[fmt.Sprintf("%s:%s", f.Key, d.VariantKey)]
				if !found {
					return fmt.Errorf("finding variant: %s; flag: %s", d.VariantKey, f.Key)
				}

				_, err := i.creator.CreateDistribution(ctx, &flipt.CreateDistributionRequest{
					FlagKey:      f.Key,
					RuleId:       rule.Id,
					VariantId:    variant.Id,
					Rollout:      d.Rollout,
					NamespaceKey: namespace,
				})

				if err != nil {
					return fmt.Errorf("creating distribution: %w", err)
				}
			}
		}

		// support explicitly setting flag type from 1.1
		if len(f.Rollouts) > 0 {
			if err := ensureFieldSupported("flag.rollouts", semver.Version{
				Major: 1,
				Minor: 1,
			}, v); err != nil {
				return err
			}

			for idx, r := range f.Rollouts {
				if r.Segment != nil && r.Threshold != nil {
					return fmt.Errorf(`rollout "%s/%s/%d" cannot have both segment and percentage rule`,
						namespace,
						f.Key,
						idx,
					)
				}

				req := &flipt.CreateRolloutRequest{
					NamespaceKey: namespace,
					FlagKey:      f.Key,
					Description:  r.Description,
					Rank:         int32(idx + 1),
				}

				if r.Segment != nil {
					frs := &flipt.RolloutSegment{
						Value:      r.Segment.Value,
						SegmentKey: r.Segment.Key,
					}

					if len(r.Segment.Keys) > 0 && r.Segment.Key != "" {
						return fmt.Errorf("rollout %s/%s/%d cannot have both segment.keys and segment.key",
							namespace,
							f.Key,
							idx,
						)
					}

					// support explicitly setting only "keys" on rules from 1.2
					if len(r.Segment.Keys) > 0 {
						if err := ensureFieldSupported("flag.rollouts[*].segment.keys", semver.Version{
							Major: 1,
							Minor: 2,
						}, v); err != nil {
							return err
						}

						frs.SegmentKeys = r.Segment.Keys
					}

					if frs.SegmentKey != "" || len(frs.SegmentKeys) == 1 {
						frs.SegmentOperator = flipt.SegmentOperator_OR_SEGMENT_OPERATOR
					} else {
						frs.SegmentOperator = flipt.SegmentOperator(flipt.SegmentOperator_value[r.Segment.Operator])
					}

					req.Rule = &flipt.CreateRolloutRequest_Segment{
						Segment: frs,
					}
				} else if r.Threshold != nil {
					req.Rule = &flipt.CreateRolloutRequest_Threshold{
						Threshold: &flipt.RolloutThreshold{
							Percentage: r.Threshold.Percentage,
							Value:      r.Threshold.Value,
						},
					}
				}

				if _, err := i.creator.CreateRollout(ctx, req); err != nil {
					return fmt.Errorf("creating rollout: %w", err)
				}
			}
		}
	}

	return nil
}

// convert converts each encountered map[interface{}]interface{} to a map[string]interface{} value.
// This is necessary because the json library does not support map[interface{}]interface{} values which nested
// maps get unmarshalled into from the yaml library.
func convert(i interface{}) interface{} {
	switch x := i.(type) {
	case map[interface{}]interface{}:
		m := map[string]interface{}{}
		for k, v := range x {
			if sk, ok := k.(string); ok {
				m[sk] = convert(v)
			}
		}
		return m
	case []interface{}:
		for i, v := range x {
			x[i] = convert(v)
		}
	}
	return i
}

func ensureFieldSupported(field string, expected, have semver.Version) error {
	if have.LT(expected) {
		return fmt.Errorf("%s is supported in version >=%s, found %s",
			field,
			versionString(expected),
			versionString(have))
	}

	return nil
}

package ext

import (
	"context"
	"encoding/json"
	"fmt"
	"io"

	"github.com/blang/semver/v4"
	"go.flipt.io/flipt/rpc/flipt"
	"gopkg.in/yaml.v2"
)

const (
	defaultBatchSize = 25
)

var (
	latestVersion     = semver.Version{Major: 1, Minor: 2}
	supportedVersions = semver.Versions{
		{Major: 1},
		latestVersion,
	}
)

type Lister interface {
	ListFlags(context.Context, *flipt.ListFlagRequest) (*flipt.FlagList, error)
	ListSegments(context.Context, *flipt.ListSegmentRequest) (*flipt.SegmentList, error)
	ListRules(context.Context, *flipt.ListRuleRequest) (*flipt.RuleList, error)
	ListRollouts(context.Context, *flipt.ListRolloutRequest) (*flipt.RolloutList, error)
}

type Exporter struct {
	store     Lister
	batchSize int32
	namespace string
}

func NewExporter(store Lister, namespace string) *Exporter {
	return &Exporter{
		store:     store,
		batchSize: defaultBatchSize,
		namespace: namespace,
	}
}

// We currently only do minor bumps and print out just major.minor
func versionString(v semver.Version) string {
	return fmt.Sprintf("%d.%d", v.Major, v.Minor)
}

func (e *Exporter) Export(ctx context.Context, w io.Writer) error {
	var (
		enc       = yaml.NewEncoder(w)
		doc       = new(Document)
		batchSize = e.batchSize
	)

	doc.Version = versionString(latestVersion)
	doc.Namespace = e.namespace

	defer enc.Close()

	var (
		remaining = true
		nextPage  string
	)

	// export flags/variants in batches
	for batch := int32(0); remaining; batch++ {
		resp, err := e.store.ListFlags(
			ctx,
			&flipt.ListFlagRequest{
				NamespaceKey: e.namespace,
				PageToken:    nextPage,
				Limit:        batchSize,
			},
		)
		if err != nil {
			return fmt.Errorf("getting flags: %w", err)
		}

		flags := resp.Flags
		nextPage = resp.NextPageToken
		remaining = nextPage != ""

		for _, f := range flags {
			flag := &Flag{
				Key:         f.Key,
				Name:        f.Name,
				Type:        f.Type.String(),
				Description: f.Description,
				Enabled:     f.Enabled,
			}

			// map variant id => variant key
			variantKeys := make(map[string]string)

			for _, v := range f.Variants {
				var attachment interface{}

				if v.Attachment != "" {
					if err := json.Unmarshal([]byte(v.Attachment), &attachment); err != nil {
						return fmt.Errorf("unmarshaling variant attachment: %w", err)
					}
				}

				flag.Variants = append(flag.Variants, &Variant{
					Key:         v.Key,
					Name:        v.Name,
					Description: v.Description,
					Attachment:  attachment,
				})

				variantKeys[v.Id] = v.Key
			}

			// export rules for flag
			resp, err := e.store.ListRules(
				ctx,
				&flipt.ListRuleRequest{
					NamespaceKey: e.namespace,
					FlagKey:      flag.Key,
				},
			)
			if err != nil {
				return fmt.Errorf("getting rules for flag %q: %w", flag.Key, err)
			}

			rules := resp.Rules
			for _, r := range rules {
				rule := &Rule{}
				var keys []string
				operator := flipt.SegmentOperator_OR_SEGMENT_OPERATOR
				if r.SegmentKey != "" {
					keys = []string{r.SegmentKey}
				} else if len(r.SegmentKeys) > 0 {
					keys = r.SegmentKeys
					if len(keys) > 1 {
						operator = r.SegmentOperator
					}
				} else {
					return fmt.Errorf("rule %q for flag %q has no segment", r.Id, flag.Key)
				}

				if operator != flipt.SegmentOperator_OR_SEGMENT_OPERATOR && operator != flipt.SegmentOperator_AND_SEGMENT_OPERATOR {
					return fmt.Errorf("rule %q for flag %q has invalid segment operator %d", r.Id, flag.Key, operator)
				}
				rule.Segment = &SegmentEmbed{IsSegment: Segments{
					Keys:            keys,
					SegmentOperator: operator.String(),
				}}

				for _, d := range r.Distributions {
					rule.Distributions = append(rule.Distributions, &Distribution{
						VariantKey: variantKeys[d.VariantId],
						Rollout:    d.Rollout,
					})
				}

				flag.Rules = append(flag.Rules, rule)
			}

			rollouts, err := e.store.ListRollouts(ctx, &flipt.ListRolloutRequest{
				NamespaceKey: e.namespace,
				FlagKey:      flag.Key,
			})
			if err != nil {
				return fmt.Errorf("getting rollout rules for flag %q: %w", flag.Key, err)
			}

			for _, r := range rollouts.Rules {
				rollout := Rollout{
					Description: r.Description,
				}

				switch rule := r.Rule.(type) {
				case *flipt.Rollout_Segment:
					rollout.Segment = &SegmentRule{
						Value: rule.Segment.Value,
					}

					if rule.Segment.SegmentKey != "" {
						rollout.Segment.Key = rule.Segment.SegmentKey
					} else if len(rule.Segment.SegmentKeys) > 0 {
						rollout.Segment.Keys = rule.Segment.SegmentKeys
					}

					if len(rule.Segment.SegmentKeys) > 1 &&
						rule.Segment.SegmentKey == "" &&
						rule.Segment.SegmentOperator == flipt.SegmentOperator_AND_SEGMENT_OPERATOR {
						rollout.Segment.Operator = rule.Segment.SegmentOperator.String()
					}
				case *flipt.Rollout_Threshold:
					rollout.Threshold = &ThresholdRule{
						Percentage: rule.Threshold.Percentage,
						Value:      rule.Threshold.Value,
					}
				}

				flag.Rollouts = append(flag.Rollouts, &rollout)
			}

			doc.Flags = append(doc.Flags, flag)
		}
	}

	remaining = true
	nextPage = ""

	// export segments/constraints in batches
	for batch := int32(0); remaining; batch++ {
		resp, err := e.store.ListSegments(
			ctx,
			&flipt.ListSegmentRequest{
				NamespaceKey: e.namespace,
				PageToken:    nextPage,
				Limit:        batchSize,
			},
		)
		if err != nil {
			return fmt.Errorf("getting segments: %w", err)
		}

		segments := resp.Segments
		nextPage = resp.NextPageToken
		remaining = nextPage != ""

		for _, s := range segments {
			segment := &Segment{
				Key:         s.Key,
				Name:        s.Name,
				Description: s.Description,
				MatchType:   s.MatchType.String(),
			}

			for _, c := range s.Constraints {
				segment.Constraints = append(segment.Constraints, &Constraint{
					Type:        c.Type.String(),
					Property:    c.Property,
					Operator:    c.Operator,
					Value:       c.Value,
					Description: c.Description,
				})
			}

			doc.Segments = append(doc.Segments, segment)
		}
	}

	if err := enc.Encode(doc); err != nil {
		return fmt.Errorf("marshaling document: %w", err)
	}

	return nil
}

